```ts
type AuthFnAdminAuthorize = (
  ctx: { request: Request; action: 'users.list' | 'users.delete' },
  input: { operationId: string; params?; query?; body? }
) => Promise<boolean | { allowed: boolean; actorId?: string; metadata?: Record<string, unknown> }>;
```

