/**
 * Shared adapter conformance test harness.
 *
 * Every SearchAdapter implementation MUST pass all assertions defined here.
 * To use: call `runConformanceSuite(adapterFactory)` inside a `describe` block.
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import type {
  InitializeResourceConfig,
  SearchAdapter,
  SearchAllResult,
  SearchDocument,
} from "./index";
import { SEARCH_ADAPTER_DISPOSED } from "./index";

export interface ConformanceAdapterFactory {
  /** Human-readable adapter name for test labels */
  name: string;
  /** Create a fresh adapter instance for each test */
  create(): SearchAdapter;
  /** Whether this adapter supports persistent storage (survives dispose+reinitialize) */
  persistent?: boolean;
  /** Whether cleanup is needed after tests (e.g., external services) */
  cleanup?(): Promise<void>;
  /** Optional callback that returns true when tests should be skipped (e.g., backend unavailable) */
  shouldSkip?(): boolean;
}

const ITEMS: InitializeResourceConfig[] = [{ name: "items", searchFields: ["title"] }];
const ITEMS_AND_NOTES: InitializeResourceConfig[] = [
  { name: "items", searchFields: ["title"] },
  { name: "notes", searchFields: ["body"] },
];

async function initialize(
  adapter: SearchAdapter,
  resources: InitializeResourceConfig[] = ITEMS
): Promise<void> {
  if (adapter.initialize) {
    await adapter.initialize({ resources });
  }
}

async function index(
  adapter: SearchAdapter,
  documents: SearchDocument[],
  resource = "items"
): Promise<void> {
  await adapter.index({ resource, documents });
}

function compareText(left: string, right: string): number {
  if (left === right) return 0;
  return left < right ? -1 : 1;
}

function compareSearchAllResults(left: SearchAllResult, right: SearchAllResult): number {
  if (left.score !== right.score) {
    if (Number.isNaN(left.score)) return Number.isNaN(right.score) ? 0 : 1;
    if (Number.isNaN(right.score)) return -1;
    return left.score > right.score ? -1 : 1;
  }

  const resourceDifference = compareText(left.resource, right.resource);
  if (resourceDifference !== 0) return resourceDifference;

  return compareText(String(left.id), String(right.id));
}

/**
 * Run the full conformance suite against an adapter.
 * Call this inside a `describe()` block.
 */
export function runConformanceSuite(factory: ConformanceAdapterFactory): void {
  let adapter: SearchAdapter;

  beforeEach((ctx) => {
    if (factory.shouldSkip?.()) {
      ctx.skip();
      return;
    }
    adapter = factory.create();
  });

  afterEach(async () => {
    if (adapter.dispose) {
      await adapter.dispose();
    }
    if (factory.cleanup) {
      await factory.cleanup();
    }
  });

  describe("contract shape", () => {
    it("has a non-empty name", () => {
      expect(typeof adapter.name).toBe("string");
      expect(adapter.name.length).toBeGreaterThan(0);
    });

    it("exposes required methods", () => {
      expect(typeof adapter.index).toBe("function");
      expect(typeof adapter.search).toBe("function");
      expect(typeof adapter.remove).toBe("function");
      expect(typeof adapter.clear).toBe("function");
    });

    it("exposes capabilities object if declared", () => {
      if (adapter.capabilities !== undefined) {
        expect(typeof adapter.capabilities).toBe("object");
      }
    });
  });

  describe("index and search", () => {
    it("returns matching ids after indexing documents", async () => {
      await initialize(adapter);
      await index(adapter, [
        { id: "d1", fields: { title: "alpha beta" } },
        { id: "d2", fields: { title: "gamma delta" } },
      ]);
      const results = await adapter.search({ resource: "items", query: "alpha", limit: 10 });
      expect(results).toContain("d1");
      expect(results).not.toContain("d2");
    });

    it("returns empty array when no documents match", async () => {
      await initialize(adapter);
      await index(adapter, [{ id: "d1", fields: { title: "alpha" } }]);
      const results = await adapter.search({ resource: "items", query: "zzzzz", limit: 10 });
      expect(results).toEqual([]);
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SEARCH_ADAPTER_DISPOSED, SearchAdapterError } from "../src/index";
import { CONFORMANCE_ASSERTIONS, runConformanceSuite } from "../src/testing";
import { searchfnAdapterVitestConfig } from "../adapter-vitest.config";

const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as {
  exports: { "./testing": { types?: string; import?: string; require?: string } };
};

describe("adapter contracts scaffolding", () => {
  it("exports constants and errors", () => {
    expect(SEARCH_ADAPTER_DISPOSED).toBe("SEARCH_ADAPTER_DISPOSED");
    const err = new SearchAdapterError("X", "msg");
    expect(err.code).toBe("X");
  });

  it("exports the shared conformance harness", () => {
    expect(typeof runConformanceSuite).toBe("function");
    expect(CONFORMANCE_ASSERTIONS.length).toBeGreaterThan(0);
  });

  it("advertises the testing subpath as ESM-only", () => {
    expect(pkg.exports["./testing"].import).toBe("./dist/testing.js");
    expect(pkg.exports["./testing"].require).toBeUndefined();
  });

  it("preserves object-form aliases in shared adapter Vitest config", () => {
    const config = searchfnAdapterVitestConfig({
      resolve: { alias: { "@fixture": "/tmp/fixture.ts" } }
    });

    expect(config.resolve?.alias).toMatchObject({
      "@fixture": "/tmp/fixture.ts",
      "@searchfn/adapter-contracts": expect.stringContaining("src/index.ts"),
      "@searchfn/adapter-contracts/testing": expect.stringContaining("src/testing.ts")
    });
  });

  it("preserves array-form aliases in shared adapter Vitest config", () => {
    const config = searchfnAdapterVitestConfig({
      resolve: { alias: [{ find: "@fixture", replacement: "/tmp/fixture.ts" }] }
    });

    expect(config.resolve?.alias).toEqual([
      {
        find: "@searchfn/adapter-contracts/testing",
        replacement: expect.stringContaining("src/testing.ts")
      },
      {
        find: "@searchfn/adapter-contracts",
        replacement: expect.stringContaining("src/index.ts")
      },
      { find: "@fixture", replacement: "/tmp/fixture.ts" }
    ]);
  });
});

