import fs from 'node:fs';
import path from 'node:path';

import type { SuperfunctionsConfig } from '../index.js';

export async function loadConfig(configPath: string): Promise<SuperfunctionsConfig | null> {
  const resolved = path.resolve(process.cwd(), configPath);
  if (!fs.existsSync(resolved)) return null;

  const ext = path.extname(resolved);
  if (ext === '.js' || ext === '.mjs' || ext === '.cjs') {
    const mod = await import(pathToFileUrl(resolved));
    return (mod.default ?? mod)?.adapter ? (mod.default ?? mod) as SuperfunctionsConfig : (mod.default ?? mod).config ?? (mod.default ?? mod);
  }
  if (ext === '.json') {
    const raw = fs.readFileSync(resolved, 'utf8');
    return JSON.parse(raw) as SuperfunctionsConfig;
  }
  if (ext === '.ts') {
    // We don't ship a TS runtime loader to keep deps slim. Suggest using JS for now.
    throw new Error('TypeScript config is not supported at runtime. Use superfunctions.config.js or JSON, or precompile your TS config.');
  }
  throw new Error(`Unsupported config extension: ${ext}`);
}

export function ensureConfigPath(p?: string) {
  return p ?? 'superfunctions.config.js';
}

function pathToFileUrl(p: string) {
  const u = new URL('file://');
  // On Windows path.resolve returns backslashes; URL needs forward slashes
  u.pathname = p.split(path.sep).join(path.posix.sep);
  return u.href;
}/**
 * @superfunctions/cli
 *
 * CLI tool for schema management and migrations
 */

// Re-export types from @superfunctions/db
import type { RuntimeStores } from '@superfunctions/db';

export type {
  TableSchema,
  TableSchemaMap,
  FieldSchema,
  IndexSchema,
  RuntimeStores,
} from '@superfunctions/db';

// Config types
export interface SuperfunctionsConfig {
  adapter: AdapterConfig;
  migrationsDir?: string;
  stores?: RuntimeStores;

  // Array of file paths that contain library initializations
  // Example: ['./src/conduct.ts', './src/auth.ts']
  libraries?: string[];

  // Auto-discover library initialization files
  // true: Use default patterns
  // object: Custom patterns and exclusions
  autoDiscover?: boolean | {
    patterns: string[];
    exclude?: string[];
  };
}

export interface AdapterConfig {
  type: 'drizzle' | 'prisma' | 'kysely';  // TODO: Add 'mongodb' when MongoDBConfig is implemented
  drizzle?: DrizzleConfig;
  prisma?: PrismaConfig;
  kysely?: KyselyConfig;
}

export interface DrizzleConfig {
  dialect: 'postgres' | 'mysql' | 'sqlite';
  connectionString?: string;
  filename?: string;
  poolConfig?: any;
  schema?: Record<string, any>;
  schemaVersionsTable?: any;
}

export interface PrismaConfig {
  prisma: any;
  modelMap?: Record<string, string>;
  schemaVersionsTable?: string;
}

export interface KyselyConfig {
  dialect: 'postgres' | 'mysql' | 'sqlite';
  connectionString?: string;
  filename?: string;
  poolConfig?: any;
  schemaVersionsTable?: string;
}

export function defineConfig(config: SuperfunctionsConfig): SuperfunctionsConfig {
  return config;
}

