      switch (baseType) {
        case 'string':
          {
            const length = mysqlVarcharLength(field);
            return length === null ? 'TEXT' : `VARCHAR(${length})`;
          }
        case 'number':
          return 'INT';
        case 'bigint':
          return 'BIGINT';
        case 'boolean':
          return 'BOOLEAN';
        case 'json':
          return 'JSON';
        default:
          return 'TEXT';
