describe('DrizzleAdapter - Postgres/MySQL Dialect Support', () => {
  /**
   * This test verifies that the dialect-aware execution paths work correctly.
   * We verify that db.execute() is called instead of db.run()/db.all() for Postgres/MySQL.
   */
  it('should use db.execute() for Postgres dialect instead of db.run()/db.all()', async () => {
    const executeCalls: any[] = [];

    // Mock Postgres Drizzle instance (no run/all methods, only execute)
    const mockDb = {
      async execute(query: any): Promise<any> {
        executeCalls.push({ type: 'execute', query });
        // Return empty result for DDL, rows array for SELECT, rowCount for DML
        const queryStr = query.queryChunks 
          ? query.queryChunks.map((chunk: any) => (typeof chunk === 'string' ? chunk : '?')).join('')
          : '';
        if (queryStr.includes('CREATE TABLE')) return { rowCount: 0 };
        if (queryStr.includes('SELECT')) return [];
        return { rowCount: 0 };
      },
    };

    const adapter = drizzleAdapter({
      db: mockDb,
      dialect: 'postgres',
      debug: false,
    });

    // Verify ensureTable uses db.execute()
    await adapter.internal.ensureTable('__datafn_test', [
      { name: 'id', type: 'text', primaryKey: true },
    ]);

    expect(executeCalls.length).toBeGreaterThan(0);
    expect(executeCalls[0].type).toBe('execute');

    // Verify create uses db.execute()
    executeCalls.length = 0;
    await adapter.internal.create('__datafn_test', { id: 'test' });
    expect(executeCalls.length).toBeGreaterThan(0);
    expect(executeCalls[0].type).toBe('execute');

    // Verify findOne uses db.execute()
    executeCalls.length = 0;
    await adapter.internal.findOne('__datafn_test', [{ field: 'id', op: 'eq', value: 'test' }]);
    expect(executeCalls.length).toBeGreaterThan(0);
    expect(executeCalls[0].type).toBe('execute');
  });

  it('should use db.execute() for MySQL dialect', async () => {
    const executeCalls: any[] = [];

    // Mock MySQL Drizzle instance (no run/all methods, only execute)
    const mockDb = {
      async execute(query: any): Promise<any> {
        executeCalls.push({ type: 'execute', query });
        const queryStr = query.queryChunks 
          ? query.queryChunks.map((chunk: any) => (typeof chunk === 'string' ? chunk : '?')).join('')
          : '';
        if (queryStr.includes('CREATE TABLE')) return { rowsAffected: 0 };
        if (queryStr.includes('SELECT')) return { rows: [] };
        return { rowsAffected: 0 };
      },
    };

    const adapter = drizzleAdapter({
      db: mockDb,
      dialect: 'mysql',
      debug: false,
    });

    // Verify ensureTable uses db.execute()
    await adapter.internal.ensureTable('__datafn_test', [
      { name: 'id', type: 'text', primaryKey: true },
    ]);

    expect(executeCalls.length).toBeGreaterThan(0);
    expect(executeCalls[0].type).toBe('execute');
  });
});

it('rejects per-call isolation when the dialect does not implement it', async () => {
  const callback = vi.fn();
  const transaction = vi.fn();
  const adapter = drizzleAdapter({ db: { transaction }, dialect: 'mysql' });
  await expect(adapter.transaction(callback,{isolationLevel:'repeatable_read'})).rejects.toThrow('unsupported');
  expect(callback).not.toHaveBeenCalled();
  expect(transaction).not.toHaveBeenCalled();
});

it('advertises and maps every PostgreSQL isolation level exposed by the shared contract', async () => {
  const transaction = vi.fn(async (callback: (trx: unknown) => Promise<unknown>, options: unknown) => callback({}));
  const adapter = drizzleAdapter({ db: { transaction }, dialect: 'postgres' });

  expect(adapter.capabilities.transactions.isolation).toEqual([
    'read_uncommitted',
    'read_committed',
    'repeatable_read',
    'serializable',
  ]);
  await adapter.transaction(async () => 'ok', { isolationLevel: 'read_uncommitted' });
  expect(transaction).toHaveBeenCalledWith(expect.any(Function), { isolationLevel: 'read uncommitted' });
});
import { describe, expect, it, vi } from 'vitest';
import { mysqlTable, varchar } from 'drizzle-orm/mysql-core';
import { drizzleAdapter } from './index.js';

const users = mysqlTable('users', {
  id: varchar('id', { length: 255 }).primaryKey(),
  name: varchar('name', { length: 255 }),
  email: varchar('email', { length: 255 }),
});

describe('DrizzleAdapter - MySQL upsert follow-ups', () => {
  it('throws when MySQL upsert cannot reselect the inserted row', async () => {
    const insertExecute = vi.fn(async () => ({ rowsAffected: 1 }));
    const duplicateExecute = vi.fn(async () => ({ rowsAffected: 1 }));
    const onDuplicateKeyUpdate = vi.fn(() => ({
      execute: duplicateExecute,
    }));
    const reselectExecute = vi.fn(async () => []);

    const mockDb = {
      _: {
        fullSchema: {
          users,
        },
      },
      insert() {
        return {
          values() {
            return {
              execute: insertExecute,
              onDuplicateKeyUpdate,
            };
          },
        };
      },
      select() {
        return {
          from() {
            return {
              where() {
                return {
                  limit() {
                    return {
                      execute: reselectExecute,
                    };
                  },
                };
              },
            };
          },
        };
      },
    };

    const adapter = drizzleAdapter({
      db: mockDb,
      dialect: 'mysql',
      debug: false,
    });

    await expect(
      adapter.upsert({
        model: 'users',
        where: [{ field: 'id', operator: 'eq', value: 'u1' }],
        create: { id: 'u1', name: 'Ada', email: 'ada@example.com' },
        update: {},
      }),
    ).rejects.toThrow('Upsert failed to return a row');

    expect(insertExecute).toHaveBeenCalledTimes(1);
    expect(onDuplicateKeyUpdate).not.toHaveBeenCalled();
    expect(duplicateExecute).not.toHaveBeenCalled();
    expect(reselectExecute).toHaveBeenCalledTimes(1);
  });
});

